#!ibl edition=2
[def:부동산준비읽기]($폴더,$슬러그="") {
  $파일 = [{kind:"config",path:f"${폴더}/_report_config.json"},{kind:"rotation",path:f"${폴더}/db/rotation.json"},{kind:"thesis",path:f"${폴더}/_thesis.md"}]
  $문서 = $파일 >> [table:each]{parallel:3} {
    [try] {
      $읽기 = [self:read]{path:$it.path}
      return {kind:$it.kind,path:$it.path,ok:true,text:$읽기.text}
    } [catch] { return {kind:$it.kind,path:$it.path,ok:false,error:$error} }
  }
  $이전 = [self:list]{path:$폴더,pattern:"housing_report_*.md"}
  $직전 = $이전 >> [table:filter]{where:($행)=>get($행,"is_dir",false)==false} >> [table:sort]{by:"name",descending:true} >> [table:take]{n:1} >> [table:each] {
    $읽기 = [self:read]{path:$it.path}
    return {kind:"previous",path:$it.path,ok:true,text:$읽기.text}
  }
  $지역 = []
  [if:$슬러그!=""] {
    $지역파일 = [self:list]{path:f"${폴더}/db/regions",pattern:f"${슬러그}.json"}
    $지역 = $지역파일 >> [table:each] {
      $읽기 = [self:read]{path:$it.path}
      return {kind:"region",path:$it.path,ok:true,text:$읽기.text}
    }
  }
  $실패 = $문서 >> [table:filter]{where:($행)=>$행.ok==false}
  return {ok:len($실패)==0,documents:$문서+ $직전+ $지역,failed:len($실패),previous_found:len($직전)>0,region_requested:$슬러그,region_found:len($지역)>0}
}

#!ibl edition=2
[def:부동산기본수집]($지역,$법정동코드,$예산,$기간) {
  [if:$예산.jeonse_min<0 or $예산.jeonse_max<$예산.jeonse_min] { return {ok:false,error:"예산은 만원 단위의 0 이상 하한·상한이어야 합니다",items:[],failed:0} }
  $조회 = [{source:"naver",type:"house",deal:"rent"},{source:"naver",type:"apt",deal:"rent"},{source:"zigbang",type:"villa",deal:"rent"},{source:"molit",type:"apt",deal:"rent"},{source:"molit",type:"apt",deal:"trade"}]
  $결과 = $조회 >> [table:each]{parallel:3} {
    [try] {
      [if:$it.source=="molit"] {
        $자료 = [sense:realty]{op:"query",source:"molit",region_code:$법정동코드,type:$it.type,deal:$it.deal,start_month:$기간.start_month,end_month:$기간.end_month}
      } [else] {
        [if:$it.source=="naver"] {
          $자료 = [sense:realty]{op:"query",source:"naver",region:$지역,type:$it.type,deal:"rent",lease:"전세",deposit_min:$예산.jeonse_min,deposit_max:$예산.jeonse_max,limit:60}
        } [else] {
          $자료 = [sense:realty]{op:"query",source:"zigbang",region:$지역,type:"villa",deal:"rent",lease:"전세",deposit_max:$예산.jeonse_max,limit:60}
        }
      }
      return {query:$it,ok:true,count:len($자료.items),data:$자료}
    } [catch] { return {query:$it,ok:false,error:$error} }
  }
  $실패 = $결과 >> [table:filter]{where:($행)=>$행.ok==false}
  return {ok:len($실패)==0,items:$결과,failed:len($실패),region:$지역,region_code:$법정동코드,period:$기간,budget_unit:"만원"}
}

#!ibl edition=2
[def:전세예산추리기]($목록,$출처,$하한만원,$상한만원) {
  [if:not ($출처 in ["naver","zigbang"]) or $하한만원<0 or $상한만원<$하한만원] {
    return {ok:false,error:"출처 naver/zigbang 및 만원 단위의 올바른 예산을 지정하세요",items:[],review:[]}
  }
  $판정 = $목록 >> [table:each] {
    [try] {
      $설명 = get($it,"meta",null)
      [if:len($설명)<2 or $설명[0]!="전" or $설명[1]!="세"] { return {status:"other_deal",original:$it} }
      [if:$출처=="naver"] { $만원 = number(get($it,"price",null))/10000 }
      [else] {
        $만원 = number(get($it,"deposit",null))
        [if:number(get($it,"rent",null))!=0] { return {status:"review",reason:"전세 표기와 월세액 충돌",original:$it} }
      }
      [if:$만원<$하한만원 or $만원>$상한만원] { return {status:"outside_budget",original:$it} }
      [if:len(get($it,"url",null))==0] { return {status:"review",reason:"매물 URL 없음",original:$it} }
      return {status:"candidate",source:$출처,deposit_man:$만원,url:get($it,"url",null),original:$it}
    } [catch] { return {status:"review",error:$error,original:$it} }
  }
  $후보 = $판정 >> [table:filter]{where:($행)=>$행.status=="candidate"}
  $확인 = $판정 >> [table:filter]{where:($행)=>$행.status=="review"}
  $그외 = $판정 >> [table:filter]{where:($행)=>$행.status=="other_deal"}
  $예산밖 = $판정 >> [table:filter]{where:($행)=>$행.status=="outside_budget"}
  return {ok:len($확인)==0,items:$후보,review:$확인,input_count:len($목록),other_deal:len($그외),outside_budget:len($예산밖),note:"예산 후보이며 주거 철학·안전 평가 통과를 뜻하지 않습니다. 중복 URL과 동일 주택은 후속 평가에서 대조합니다."}
}

#!ibl edition=2
[def:매물재방문비교]($기존,$현재) {
  $변동 = $기존 >> [table:each] {
    $옛것 = $it
    $일치 = $현재 >> [table:filter]{where:($행)=>$행.id==$옛것.id}
    [if:get($옛것,"status","")=="rejected"] { return {id:$옛것.id,status:"rejected",previous:$옛것} }
    [if:len($일치)==0] { return {id:$옛것.id,status:"needs_recheck",previous:$옛것} }
    [if:len($일치)>1] { return {id:$옛것.id,status:"conflict",previous:$옛것,current:$일치} }
    [if:$일치[0].price!=$옛것.price] { return {id:$옛것.id,status:"changed",previous:$옛것,current:$일치[0]} }
    return {id:$옛것.id,status:"unchanged",previous:$옛것,current:$일치[0]}
  }
  $새것 = $현재 >> [table:each]{mode:"flat_map"} {
    $현재행 = $it
    $일치 = $기존 >> [table:filter]{where:($행)=>$행.id==$현재행.id}
    [if:len($일치)==0] { return [{id:$현재행.id,status:"new",current:$현재행}] }
    return []
  }
  return {items:$변동+ $새것,note:"양쪽 price는 같은 단위·거래 형식이어야 합니다. 검색 누락은 소멸 증거가 아니며 needs_recheck는 링크 재확인 대상입니다. DB를 쓰지 않습니다."}
}
